CREATE TYPE "FreightServiceStatus" AS ENUM ('AVAILABLE','PARTNER_REQUIRED','COMING_SOON','CONFIGURATION_REQUIRED','DISABLED');
CREATE TYPE "ComplianceVerificationStatus" AS ENUM ('VERIFIED','EXPIRING','INFORMATION_REQUIRED','REVIEW','RESTRICTED');
CREATE TABLE "FreightServicePartner" ("id" TEXT NOT NULL,"tenantId" TEXT,"serviceType" TEXT NOT NULL,"name" TEXT NOT NULL,"status" "FreightServiceStatus" NOT NULL DEFAULT 'PARTNER_REQUIRED',"providerKey" TEXT NOT NULL,"regionsJson" JSONB NOT NULL,"eligibilityRulesJson" JSONB,"referralConfigJson" JSONB,"revenueShareBps" INTEGER,"externalApiConfigured" BOOLEAN NOT NULL DEFAULT false,"enabled" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FreightServicePartner_pkey" PRIMARY KEY ("id"));
CREATE TABLE "FreightServiceApplication" ("id" TEXT NOT NULL,"tenantId" TEXT,"userId" TEXT NOT NULL,"partnerId" TEXT,"serviceType" TEXT NOT NULL,"transactionId" TEXT,"invoiceReference" TEXT,"invoiceAmountCents" INTEGER,"advanceBasisPoints" INTEGER,"feeCents" INTEGER,"netAmountCents" INTEGER,"currency" TEXT NOT NULL DEFAULT 'cad',"status" TEXT NOT NULL DEFAULT 'INFORMATION_REQUIRED',"externalReference" TEXT,"agreementSnapshotJson" JSONB,"providerPayloadJson" JSONB,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "FreightServiceApplication_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CarrierComplianceRecord" ("id" TEXT NOT NULL,"tenantId" TEXT,"carrierUserId" TEXT NOT NULL,"legalName" TEXT NOT NULL,"jurisdiction" TEXT NOT NULL,"registrationType" TEXT NOT NULL,"registrationNumber" TEXT NOT NULL,"authorityStatus" "ComplianceVerificationStatus" NOT NULL DEFAULT 'INFORMATION_REQUIRED',"operatingRegions" JSONB NOT NULL,"equipmentJson" JSONB,"requiredDocuments" JSONB,"checklistJson" JSONB NOT NULL,"sourceType" TEXT NOT NULL DEFAULT 'SELF_REPORTED',"externalReference" TEXT,"lastCheckedAt" TIMESTAMP(3),"nextCheckAt" TIMESTAMP(3),"updatedById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CarrierComplianceRecord_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CarrierInsurancePolicy" ("id" TEXT NOT NULL,"tenantId" TEXT,"carrierUserId" TEXT NOT NULL,"providerName" TEXT NOT NULL,"policyType" TEXT NOT NULL,"policyNumberEncrypted" TEXT NOT NULL,"policyNumberLast4" TEXT NOT NULL,"effectiveDate" TIMESTAMP(3) NOT NULL,"expiryDate" TIMESTAMP(3) NOT NULL,"coverageAmountCents" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'cad',"documentStorageKey" TEXT,"status" "ComplianceVerificationStatus" NOT NULL DEFAULT 'INFORMATION_REQUIRED',"verifiedById" TEXT,"verifiedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CarrierInsurancePolicy_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "FreightServicePartner_tenantId_serviceType_providerKey_key" ON "FreightServicePartner"("tenantId","serviceType","providerKey"); CREATE INDEX "FreightServicePartner_serviceType_status_idx" ON "FreightServicePartner"("serviceType","status"); CREATE UNIQUE INDEX "FreightServiceApplication_idempotencyKey_key" ON "FreightServiceApplication"("idempotencyKey"); CREATE INDEX "FreightServiceApplication_tenantId_serviceType_status_idx" ON "FreightServiceApplication"("tenantId","serviceType","status"); CREATE INDEX "FreightServiceApplication_userId_createdAt_idx" ON "FreightServiceApplication"("userId","createdAt"); CREATE INDEX "FreightServiceApplication_transactionId_idx" ON "FreightServiceApplication"("transactionId"); CREATE UNIQUE INDEX "CarrierComplianceRecord_jurisdiction_registrationType_registrationNumber_key" ON "CarrierComplianceRecord"("jurisdiction","registrationType","registrationNumber"); CREATE INDEX "CarrierComplianceRecord_carrierUserId_authorityStatus_idx" ON "CarrierComplianceRecord"("carrierUserId","authorityStatus"); CREATE INDEX "CarrierInsurancePolicy_carrierUserId_status_expiryDate_idx" ON "CarrierInsurancePolicy"("carrierUserId","status","expiryDate");
ALTER TABLE "FreightServicePartner" ADD CONSTRAINT "FreightServicePartner_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "FreightServiceApplication" ADD CONSTRAINT "FreightServiceApplication_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "FreightServiceApplication" ADD CONSTRAINT "FreightServiceApplication_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CarrierComplianceRecord" ADD CONSTRAINT "CarrierComplianceRecord_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CarrierComplianceRecord" ADD CONSTRAINT "CarrierComplianceRecord_updatedById_fkey" FOREIGN KEY ("updatedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CarrierInsurancePolicy" ADD CONSTRAINT "CarrierInsurancePolicy_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "CarrierInsurancePolicy" ADD CONSTRAINT "CarrierInsurancePolicy_verifiedById_fkey" FOREIGN KEY ("verifiedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
